Mesh<Point, double> result;
std::unordered_map<RT::Vertex_handle, std::size_t> vertex_index;
std::size_t idx = 0;

for (auto vit = rt.vertices_begin(); vit != rt.vertices_end(); ++vit) {
    if (!rt.is_infinite(vit)) {
        vertex_index[vit] = idx++;
    }
}

std::vector<Point> vertices;
vertices.reserve(vertex_index.size());
for (const auto& [vh, id] : vertex_index) {
    vertices.push_back(vh->point());
}
result.vertices = std::move(vertices);

std::vector<std::array<std::size_t, 2>> edges;
std::vector<double> areas;

for (auto fit = rt.finite_facets_begin(); fit != rt.finite_facets_end(); ++fit) {
    RT::Cell_handle c = fit->first;
    int i = fit->second;

    if (rt.is_infinite(c->vertex((i + 1) % 4)) ||
        rt.is_infinite(c->vertex((i + 2) % 4)) ||
        rt.is_infinite(c->vertex((i + 3) % 4))) {
        continue;
    }

    RT::Facet f = *fit;
    RT::Cell_handle n = f.first->neighbor(f.second);

    if (rt.is_infinite(n)) continue;

    Point dual1 = rt.dual(f.first);
    Point dual2 = rt.dual(n);

    double area = std::sqrt(CGAL::squared_distance(dual1, dual2));
    if (area < threshold) continue;

    std::size_t v1 = vertex_index[f.first->vertex(f.second)];
    std::size_t v2 = vertex_index[n->vertex(rt.mirror_index(f.first, f.second))];

    edges.push_back({v1, v2});
    areas.push_back(area);
}

result.faces = std::move(edges);
result.face_areas = std::move(areas);

return result;
// END_CODE

